package com.example.inventory.services; import com.example.inventory.dao.*;import com.example.inventory.models.*;import java.sql.*;import java.util.*;public class InventoryService implements AutoCloseable{private final Connection c;private final ItemDao itemDao;private final VendorDao vendorDao;public InventoryService(Connection c){this.c=c;itemDao=new ItemDao(c);vendorDao=new VendorDao(c);}public void addItem(Item i)throws SQLException{itemDao.addItem(i);}public void updateItem(Item i)throws SQLException{itemDao.updateItem(i);}public Item getItemById(int id)throws SQLException{return itemDao.getItem(id);}public List<Item> getAllItems()throws SQLException{return itemDao.getAllItems();}public void removeItem(int id)throws SQLException{itemDao.deleteItem(id);}public void addVendor(Vendor v)throws SQLException{vendorDao.addVendor(v);}public void updateVendor(Vendor v)throws SQLException{vendorDao.updateVendor(v);}public List<Vendor> getAllVendors()throws SQLException{return vendorDao.getAllVendors();}public void removeVendor(int id)throws SQLException{vendorDao.deleteVendor(id);}public void adjustStock(int id,int qty,String type)throws SQLException{if(qty<=0)throw new IllegalArgumentException("Quantity must be positive");if(!type.equals("IN")&&!type.equals("OUT"))throw new IllegalArgumentException("Type must be IN or OUT");c.setAutoCommit(false);try{Item i=itemDao.getItem(id);if(i==null)throw new IllegalArgumentException("Item not found");int n=type.equals("IN")?i.getQuantity()+qty:i.getQuantity()-qty;if(n<0)throw new IllegalArgumentException("Insufficient stock");i.setQuantity(n);itemDao.updateItem(i);try(PreparedStatement p=c.prepareStatement("INSERT INTO stock_entries(item_id,quantity,type)VALUES(?,?,?)")){p.setInt(1,id);p.setInt(2,qty);p.setString(3,type);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}public List<Item> getLowStockItems(int t)throws SQLException{List<Item>o=new ArrayList<>();for(Item i:getAllItems())if(i.getQuantity()<=t)o.add(i);return o;}public void close()throws SQLException{c.close();}}